#include <cstdint>
#include <cstring>

namespace {
    uint32_t ftz(uint32_t x) {
        if ((x & 0x7F800000) == 0) {
            return x & 0x80000000;
        }
        return x;
    }

    uint32_t canon_nan(uint32_t x) {
        if ((x & 0x7F800000) == 0x7F800000 && (x & 0x007FFFFF) != 0) {
            return 0x7FC00000;
        }
        return x;
    }

    float u32_to_f32(uint32_t x) {
        float f;
        std::memcpy(&f, &x, 4);
        return f;
    }

    uint32_t f32_to_u32(float f) {
        uint32_t x;
        std::memcpy(&x, &f, 4);
        return x;
    }
}

void fmac_custom_iss(const uint32_t in[3], uint32_t out[3]) {
    uint32_t a_u = ftz(in[0]);
    uint32_t b_u = ftz(in[1]);
    uint32_t c_u = ftz(in[2]);

    float a = u32_to_f32(a_u);
    float b = u32_to_f32(b_u);
    float c = u32_to_f32(c_u);

    float p_f = a * b;
    uint32_t p_u = canon_nan(ftz(f32_to_u32(p_f)));

    float p_real = u32_to_f32(p_u);
    float res_f = c + p_real;
    uint32_t res_u = canon_nan(ftz(f32_to_u32(res_f)));

    out[0] = res_u;
    out[1] = 0;
    out[2] = 0;
}
